$pdo=Database::connection();$slug=trim((string)($_GET['empresa']??''));
$s=$pdo->prepare('SELECT * FROM tenants WHERE slug=? AND status="active" LIMIT 1');$s->execute([$slug]);$tenant=$s->fetch();if(!$tenant){http_response_code(404);exit('Empresa não encontrada.');}$tenantId=(int)$tenant['id'];
try{$m=$pdo->prepare('SELECT enabled FROM tenant_modules WHERE tenant_id=? AND module_key="menu" LIMIT 1');$m->execute([$tenantId]);$v=$m->fetchColumn();if($v!==false&&!(bool)$v){http_response_code(404);exit('Cardápio indisponível.');}}catch(Throwable){}
$settings=json_decode((string)($tenant['settings']??'{}'),true);if(!is_array($settings))$settings=[];$pickupEnabled=$settings['pickup_enabled']??true;$schedulingEnabled=!empty($settings['scheduling_enabled']);
$units=[];try{$u=$pdo->prepare('SELECT id,name,slug,address,city,phone FROM business_units WHERE tenant_id=? AND status="active" ORDER BY name');$u->execute([$tenantId]);$units=$u->fetchAll();}catch(Throwable){}
$unitParam=trim((string)($_GET['unidade']??''));$unit=null;if($unitParam!==''&&$units){foreach($units as$u)if((string)$u['slug']===$unitParam||(string)$u['id']===$unitParam){$unit=$u;break;}if(!$unit){http_response_code(404);exit('Unidade não encontrada.');}}elseif(count($units)===1)$unit=$units[0];$unitId=$unit?(int)$unit['id']:null;
$ordering=new OnlineOrderingService();$deliveryStatus=$ordering->statusAt($pdo,$tenantId,'delivery');$pickupStatus=$pickupEnabled?$ordering->statusAt($pdo,$tenantId,'pickup'):['open'=>false,'reason'=>'Retirada indisponível.'];$scheduler=new OrderSchedulingService();$deliverySlots=$schedulingEnabled?$scheduler->availableSlots($pdo,$tenantId,'delivery',50):[];$pickupSlots=$schedulingEnabled&&$pickupEnabled?$scheduler->availableSlots($pdo,$tenantId,'pickup',50):[];

$cartKey='menu:'.$tenantId.':'.($unitId??0);if(!isset($_SESSION['public_carts'][$cartKey])||!is_array($_SESSION['public_carts'][$cartKey]))$_SESSION['public_carts'][$cartKey]=[];$cart=&$_SESSION['public_carts'][$cartKey];$error=null;
$menuUrl=function(string $fragment='')use($slug,$unit):string{$q=['empresa'=>$slug];if($unit)$q['unidade']=$unit['slug'];return app_url('/menu.php?'.http_build_query($q).$fragment);};

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada. Atualize a página.';else try{$action=(string)($_POST['action']??'');
        if($action==='add'){$id=(int)($_POST['product_id']??0);$qty=max(1,min(50,(int)($_POST['qty']??1)));$optionIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['option_ids']??[])),fn($v)=>$v>0)));sort($optionIds);$p=$pdo->prepare('SELECT id,unit_id FROM products WHERE id=? AND tenant_id=? AND active=1');$p->execute([$id,$tenantId]);$prod=$p->fetch();if(!$prod||($unitId&&$prod['unit_id']!==null&&(int)$prod['unit_id']!==$unitId))throw new RuntimeException('Produto indisponível nesta unidade.');(new CatalogOptionsService())->validateSelection($pdo,$tenantId,$id,$optionIds);$key=hash('sha256',$id.'|'.implode(',',$optionIds));if(isset($cart[$key]))$cart[$key]['qty']=min(50,(int)$cart[$key]['qty']+$qty);else$cart[$key]=['product_id'=>$id,'qty'=>$qty,'option_ids'=>$optionIds];header('Location: '.$menuUrl('#carrinho'),true,303);exit;}
        if($action==='qty'){$key=(string)($_POST['line_key']??'');$qty=max(0,min(50,(int)($_POST['qty']??0)));if(isset($cart[$key])){if($qty===0)unset($cart[$key]);else$cart[$key]['qty']=$qty;}header('Location: '.$menuUrl('#carrinho'),true,303);exit;}
        if($action==='remove'){$key=(string)($_POST['line_key']??'');unset($cart[$key]);header('Location: '.$menuUrl('#carrinho'),true,303);exit;}
        if($action==='clear'){$cart=[];header('Location: '.$menuUrl(),true,303);exit;}
        if($action==='checkout'){$payload=array_values($cart);$buyer=['name'=>(string)($_POST['name']??''),'phone'=>(string)($_POST['phone']??''),'email'=>(string)($_POST['email']??''),'postal_code'=>(string)($_POST['postal_code']??''),'neighborhood'=>(string)($_POST['neighborhood']??''),'city'=>(string)($_POST['city']??''),'unit_id'=>$unitId];$mode=(string)($_POST['fulfillment']??'delivery');$scheduled=trim((string)($_POST['scheduled_for']??''));$service=new PublicOrderService();if($mode==='pickup')$result=$service->createPickup($tenantId,$payload,$buyer,(string)($_POST['coupon']??''),$scheduled!==''?$scheduled:null);elseif($mode==='delivery')$result=$service->createDelivery($tenantId,$payload,$buyer,(string)($_POST['address']??''),(string)($_POST['coupon']??''),$scheduled!==''?$scheduled:null);else throw new RuntimeException('Forma de recebimento inválida.');$cart=[];header('Location: '.app_url('/pedido.php?t='.urlencode($result['public_token'])),true,303);exit;}
    }catch(Throwable$e){$error=$e->getMessage();}
}

$where='tenant_id=? AND active=1';$args=[$tenantId];if($unitId){$where.=' AND (unit_id IS NULL OR unit_id=?)';$args[]=$unitId;}$c=$pdo->prepare('SELECT * FROM categories WHERE '.$where.' ORDER BY sort_order,name');$c->execute($args);$categories=$c->fetchAll();$p=$pdo->prepare('SELECT * FROM products WHERE '.$where.' ORDER BY featured DESC,category_id,name');$p->execute($args);$products=$p->fetchAll();$byId=[];foreach($products as$prod)$byId[(int)$prod['id']]=$prod;
$productIds=array_keys($byId);$groups=[];$options=[];if($productIds){$marks=implode(',',array_fill(0,count($productIds),'?'));$g=$pdo->prepare('SELECT * FROM product_option_groups WHERE tenant_id=? AND active=1 AND product_id IN ('.$marks.') ORDER BY product_id,sort_order,id');$g->execute([$tenantId,...$productIds]);foreach($g->fetchAll()as$r)$groups[(int)$r['product_id']][]=$r;$groupIds=[];foreach($groups as$rows)foreach($rows as$r)$groupIds[]=(int)$r['id'];if($groupIds){$marks=implode(',',array_fill(0,count($groupIds),'?'));$o=$pdo->prepare('SELECT * FROM product_options WHERE active=1 AND group_id IN ('.$marks.') ORDER BY group_id,sort_order,id');$o->execute($groupIds);foreach($o->fetchAll()as$r)$options[(int)$r['group_id']][]=$r;}}
$catalog=new CatalogOptionsService();$cartLines=[];$cartTotal=0;foreach($cart as$key=>$row){$id=(int)($row['product_id']??0);if(!isset($byId[$id]))continue;$prod=$byId[$id];try{$sel=$catalog->validateSelection($pdo,$tenantId,$id,(array)($row['option_ids']??[]));}catch(Throwable){continue;}$base=$prod['promo_price_cents']!==null?(int)$prod['promo_price_cents']:(int)$prod['price_cents'];$unitPrice=max(0,$base+(int)$sel['delta_cents']);$qty=(int)$row['qty'];$line=$unitPrice*$qty;$cartTotal+=$line;$cartLines[]=['key'=>$key,'product'=>$prod,'qty'=>$qty,'options'=>$sel['options'],'unit_price'=>$unitPrice,'total'=>$line];}
$zoneCount=$pdo->prepare('SELECT COUNT(*) FROM delivery_zones WHERE tenant_id=? AND active=1'.($unitId?' AND (unit_id IS NULL OR unit_id=?)':''));try{$zoneCount->execute($unitId?[$tenantId,$unitId]:[$tenantId]);$hasZones=(int)$zoneCount->fetchColumn()>0;}catch(Throwable){$hasZones=false;}
function menu_money(int$c):string{return'R$ '.number_format($c/100,2,',','.');}function menu_product_price(array$p):string{return menu_money((int)($p['promo_price_cents']??$p['price_cents']));}
$primary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($tenant['primary_color']??''))?$tenant['primary_color']:'#6d4aff';$secondary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($tenant['secondary_color']??''))?$tenant['secondary_color']:'#8b5cf6';
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($primary) ?>"><title><?= Security::e($tenant['name']) ?> — Cardápio</title><link rel="manifest" href="<?= Security::e(app_url('/manifest.webmanifest')) ?>"><link rel="stylesheet" href="<?= Security::e(app_url('/assets/app.css')) ?>?v=92legacy1"><style>:root{--brand:<?= Security::e($primary) ?>;--brand2:<?= Security::e($secondary) ?>}.menu-body{background:#f5f6fb;color:#191b24}.menu-shell{max-width:1240px;margin:auto;padding:18px 16px 100px}.menu-hero{position:relative;overflow:hidden;padding:32px;border-radius:28px;background:linear-gradient(135deg,var(--brand),var(--brand2));color:white;box-shadow:0 18px 50px #261c5f24}.menu-hero:after{content:"";position:absolute;width:280px;height:280px;border-radius:50%;background:#fff2;right:-90px;top:-110px}.menu-hero h1{font-size:clamp(30px,6vw,56px);margin:8px 0}.unit-tabs{display:flex;gap:8px;overflow:auto;padding:14px 0}.unit-tabs a{white-space:nowrap;padding:10px 14px;border-radius:999px;background:white;border:1px solid #e2e4ee;text-decoration:none;color:#343645;font-weight:700}.unit-tabs a.active{background:var(--brand);color:white;border-color:var(--brand)}.menu-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(330px,1fr);gap:18px}.category-card{background:white;border:1px solid #e6e7ef;border-radius:22px;padding:20px;margin-bottom:16px}.product{display:grid;grid-template-columns:1fr auto;gap:18px;padding:17px 0;border-top:1px solid #ececf2}.product:first-of-type{border-top:0}.product-main{display:flex;gap:14px}.product-image{width:94px;height:94px;border-radius:18px;object-fit:cover;background:#eee}.product h3{margin:0 0 5px}.badge-premium{display:inline-block;padding:4px 8px;border-radius:999px;background:#ede9fe;color:#5b21b6;font-size:.72rem;font-weight:800}.price{font-size:1.08rem;font-weight:900;color:var(--brand)}.old-price{color:#9295a4;text-decoration:line-through;font-size:.88rem}.option-box{margin:10px 0;padding:11px;border-radius:12px;background:#f7f7fb}.option-box>strong{display:block;margin-bottom:7px}.option-row{display:flex;justify-content:space-between;gap:10px;padding:5px 0;font-size:.9rem}.add-panel{min-width:190px}.cart{position:sticky;top:14px;background:white;border:1px solid #e6e7ef;border-radius:22px;padding:20px;height:max-content}.cart-line{padding:13px 0;border-bottom:1px solid #ececf2}.cart-options{font-size:.82rem;color:#747789;margin-top:4px}.qty{display:flex;gap:7px;align-items:center;margin-top:8px}.qty input{width:64px}.choice{display:grid;grid-template-columns:1fr 1fr;gap:8px}.choice label{border:1px solid #dddfea;padding:12px;border-radius:14px}.floating-cart{display:none}.menu-shell input,.menu-shell select,.menu-shell textarea{background:white;color:#222;border:1px solid #dfe1ea}.menu-shell .card{background:white;color:#222;border-color:#e6e7ef}.menu-shell .muted{color:#747789}@media(max-width:820px){.menu-grid{grid-template-columns:1fr}.cart{position:static}.product{grid-template-columns:1fr}.add-panel{min-width:0}.floating-cart{display:block;position:fixed;z-index:20;bottom:14px;left:14px;right:14px;background:var(--brand)!important;color:white!important}.menu-hero{padding:24px}.product-image{width:78px;height:78px}}</style></head><body class="menu-body"><main class="menu-shell"><section class="menu-hero"><div style="font-weight:900;opacity:.9">EventMenu Premium</div><h1><?= Security::e($tenant['name']) ?></h1><p><?= Security::e($unit?('Unidade '.$unit['name']):'Cardápio digital · delivery · retirada') ?></p><?php if(!empty($settings['menu_message'])):?><p><?= Security::e($settings['menu_message']) ?></p><?php endif;?></section><?php if(count($units)>1):?><nav class="unit-tabs"><a class="<?= !$unit?'active':'' ?>" href="<?= Security::e(app_url('/menu.php?empresa='.urlencode($slug))) ?>">Todas / compartilhados</a><?php foreach($units as$u):?><a class="<?= $unit&&(int)$unit['id']===(int)$u['id']?'active':'' ?>" href="<?= Security::e(app_url('/menu.php?empresa='.urlencode($slug).'&unidade='.urlencode($u['slug']))) ?>"><?= Security::e($u['name']) ?></a><?php endforeach;?></nav><?php endif;?><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?><div class="menu-grid"><section><?php $rendered=[];foreach($categories as$cat):$catProducts=array_values(array_filter($products,fn($p)=>(int)$p['category_id']===(int)$cat['id']));if(!$catProducts)continue;$rendered[(int)$cat['id']]=true;?><article class="category-card"><div class="section-head"><h2><?= Security::e($cat['name']) ?></h2></div><?php foreach($catProducts as$prod):?><div class="product"><div class="product-main"><?php if(!empty($prod['image_url'])):?><img class="product-image" loading="lazy" src="<?= Security::e($prod['image_url']) ?>" alt=""><?php endif;?><div><h3><?= Security::e($prod['name']) ?> <?php if($prod['badge']):?><span class="badge-premium"><?= Security::e($prod['badge']) ?></span><?php endif;?><?php if($prod['featured']):?><span class="badge-premium">Destaque</span><?php endif;?></h3><div class="muted"><?= Security::e($prod['description']??'') ?></div><?php if($prod['promo_price_cents']!==null):?><span class="old-price"><?= menu_money((int)$prod['price_cents']) ?></span> <?php endif;?><span class="price"><?= menu_product_price($prod) ?></span><?php if($prod['preparation_minutes']):?><div class="muted">≈ <?= (int)$prod['preparation_minutes'] ?> min</div><?php endif;?></div></div><form method="post" class="add-panel"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= (int)$prod['id'] ?>"><?php foreach($groups[(int)$prod['id']]??[]as$gr):?><div class="option-box"><strong><?= Security::e($gr['name']) ?> <small class="muted"><?= (int)$gr['min_select']>0?'obrigatório':'opcional' ?> · até <?= (int)$gr['max_select'] ?></small></strong><?php foreach($options[(int)$gr['id']]??[]as$op):$radio=(int)$gr['max_select']===1;?><label class="option-row"><span><input type="<?= $radio?'radio':'checkbox' ?>" <?= $radio?'name="group_'.$gr['id'].'"':'name="group_'.$gr['id'].'[]"' ?> value="<?= (int)$op['id'] ?>" onchange="this.form.querySelectorAll('[data-option-group=\'<?= (int)$gr['id'] ?>\']').forEach(i=>i.remove());const vals=this.form.querySelectorAll('[name^=\'group_<?= (int)$gr['id'] ?>\']:checked');vals.forEach(v=>{const i=document.createElement('input');i.type='hidden';i.name='option_ids[]';i.value=v.value;i.dataset.optionGroup='<?= (int)$gr['id'] ?>';this.form.appendChild(i);});" <?= $radio&&(int)$gr['min_select']>0?'required':'' ?>> <?= Security::e($op['name']) ?></span><span><?= (int)$op['price_delta_cents']===0?'':(((int)$op['price_delta_cents']>0?'+ ':'- ').menu_money(abs((int)$op['price_delta_cents']))) ?></span></label><?php endforeach;?></div><?php endforeach;?><div class="actions"><input type="number" name="qty" value="1" min="1" max="50" style="width:72px"><button class="primary">Adicionar</button></div></form></div><?php endforeach;?></article><?php endforeach;$uncat=array_values(array_filter($products,fn($p)=>!$p['category_id']));if($uncat):?><article class="category-card"><h2>Outros</h2><?php foreach($uncat as$prod):?><div class="product"><div class="product-main"><div><h3><?= Security::e($prod['name']) ?></h3><span class="price"><?= menu_product_price($prod) ?></span></div></div><form method="post" class="add-panel"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= (int)$prod['id'] ?>"><button class="primary">Adicionar</button></form></div><?php endforeach;?></article><?php endif;?><?php if(!$products):?><article class="category-card"><h2>Cardápio em preparação</h2><p class="muted">Nenhum produto disponível nesta unidade.</p></article><?php endif;?></section><aside id="carrinho" class="cart"><div class="section-head"><h2>Seu pedido</h2><?php if($cartLines):?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="clear"><button class="secondary">Limpar</button></form><?php endif;?></div><?php if(!$cartLines):?><p class="muted">Adicione itens para começar.</p><?php else:?><?php foreach($cartLines as$line):?><div class="cart-line"><strong><?= Security::e($line['product']['name']) ?></strong><?php if($line['options']):?><div class="cart-options"><?= Security::e(implode(' · ',array_column($line['options'],'name'))) ?></div><?php endif;?><div class="muted"><?= menu_money($line['unit_price']) ?> cada · <strong><?= menu_money($line['total']) ?></strong></div><div class="qty"><form method="post" class="actions"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="qty"><input type="hidden" name="line_key" value="<?= Security::e($line['key']) ?>"><input type="number" name="qty" min="0" max="50" value="<?= (int)$line['qty'] ?>"><button class="secondary">OK</button></form><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="line_key" value="<?= Security::e($line['key']) ?>"><button class="secondary">Remover</button></form></div></div><?php endforeach;?><p style="font-size:1.2rem"><strong>Produtos <span style="float:right"><?= menu_money($cartTotal) ?></span></strong></p><p class="muted">Preço, opções, estoque, cupom, frete e horário são validados novamente no servidor.</p><form method="post" class="form-grid" id="checkout-form"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="checkout"><div class="span-2"><strong>Como deseja receber?</strong><div class="choice"><label><input type="radio" name="fulfillment" value="delivery" checked> Delivery<br><small class="muted"><?= Security::e($deliveryStatus['open']?'Aberto agora':(string)$deliveryStatus['reason']) ?></small></label><?php if($pickupEnabled):?><label><input type="radio" name="fulfillment" value="pickup"> Retirar no local<br><small class="muted"><?= Security::e($pickupStatus['open']?'Aberto agora':(string)$pickupStatus['reason']) ?></small></label><?php endif;?></div></div><label class="span-2">Quando?<select name="scheduled_for" id="schedule-select" data-delivery='<?= Security::e(json_encode($deliverySlots,JSON_UNESCAPED_UNICODE|JSON_HEX_APOS|JSON_HEX_QUOT)) ?>' data-pickup='<?= Security::e(json_encode($pickupSlots,JSON_UNESCAPED_UNICODE|JSON_HEX_APOS|JSON_HEX_QUOT)) ?>'><option value="">O mais rápido possível</option></select></label><label class="span-2">Nome<input name="name" required autocomplete="name"></label><label>Telefone<input name="phone" required autocomplete="tel"></label><label>E-mail<input type="email" name="email" autocomplete="email"></label><div class="span-2" id="delivery-fields"><div class="form-grid"><label>CEP<input name="postal_code" inputmode="numeric" autocomplete="postal-code"></label><label>Bairro<input name="neighborhood"></label><label class="span-2">Cidade<input name="city"></label><label class="span-2">Endereço completo<textarea name="address"></textarea></label></div></div><label class="span-2">Cupom<input name="coupon" placeholder="Opcional"></label><?php if($hasZones):?><p class="muted span-2" id="zone-help">Taxa, mínimo e prazo são calculados pela área de entrega.</p><?php endif;?><button class="primary span-2">Continuar para pagamento</button></form><?php endif;?></aside></div><?php if($cartLines):?><a class="button primary floating-cart" href="#carrinho">Ver carrinho · <?= menu_money($cartTotal) ?></a><?php endif;?></main><script>(function(){const form=document.getElementById('checkout-form');if(!form)return;const delivery=document.getElementById('delivery-fields'),select=document.getElementById('schedule-select'),zone=document.getElementById('zone-help');const parse=v=>{try{return JSON.parse(v||'[]')}catch(e){return[]}};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const render=()=>{const checked=form.querySelector('input[name="fulfillment"]:checked');if(!checked)return;const mode=checked.value;delivery.style.display=mode==='delivery'?'block':'none';if(zone)zone.style.display=mode==='delivery'?'block':'none';select.innerHTML='<option value="">O mais rápido possível</option>'+parse(select.dataset[mode]).map(s=>'<option value="'+esc(s.value)+'">'+esc(s.label)+(s.remaining===null?'':' · '+Number(s.remaining)+' vagas')+'</option>').join('');};form.querySelectorAll('input[name="fulfillment"]').forEach(el=>el.addEventListener('change',render));render();})();if('serviceWorker'in navigator){navigator.serviceWorker.register('<?= Security::e(app_url('/sw.js')) ?>').catch(()=>{});}</script></body></html>